    status: str = Field(..., description="Status: Good, Warning, Critical")
    trend_direction: str = Field(..., description="Trend direction")
    trend_percentage: float = Field(..., description="Trend percentage")
    period_start: date = Field(..., description="Period start")
    period_end: date = Field(..., description="Period end")
    components: Dict[str, Any] = Field(default_factory=dict, description="Component breakdown")


